def transform(grid):
    import numpy as np
    g = np.array(grid)
    out = g.copy()
    # For each color, draw a ray/line between min and max coordinate or full grid
    # col 4 has 1 from 0 to 8, but output has 1 at row 9 too!
    # So it extends to the bottom boundary.
    for r in range(g.shape[0]):
        colors = set(g[r]) - {0}
        for c in colors:
            if (g[r] == c).sum() > 1:
                out[r, :] = c
    for c in range(g.shape[1]):
        colors = set(g[:, c]) - {0}
        for col in colors:
            if (g[:, c] == col).sum() > 1:
                for r in range(g.shape[0]):
                    if out[r, c] == 0:
                        out[r, c] = col
    return out.tolist()

def transform(grid):
    import numpy as np
    g = np.array(grid)
    out = g.copy()
    # Vertical lines extend, horizontal lines extend, order by color descending (8 > 1)
    for col_idx in range(g.shape[1]):
        vals = [v for v in g[:, col_idx] if v != 0]
        if len(vals) > 1 and len(set(vals)) == 1:
            out[:, col_idx] = vals[0]
    for row_idx in range(g.shape[0]):
        vals = [v for v in g[row_idx, :] if v != 0]
        if len(vals) > 1 and len(set(vals)) == 1:
            out[row_idx, :] = vals[0]
    return out.tolist()
